const portabilityStatuses=[["Conflito", "CPF divergente, linha inativa, linha em plano família ou com fidelidade.", "Verificar o status da linha com o cliente. Aguardar a correção da falha e reagendar o pedido."], ["Conflito SMS", "Cliente não respondeu ao SMS de confirmação encaminhado pela EA, conforme o material.", "Reagendar o pedido de portabilidade."], ["Erro", "Falha no preenchimento da solicitação de portabilidade.", "Reenviar a solicitação com as informações corretas."], ["Erro - Atualizar Status", "Erro durante o processo de portabilidade.", "Abrir um incidente para análise da TI Vivo."], ["Concluído", "O processo funcionou normalmente.", "Validar no Gestão de Contas e informar ao cliente."], ["Autorizado", "O pedido está em processamento.", "Aguardar a conclusão."], ["Rejeitado", "O processo foi repetido com erro anterior, ou foi solicitada portabilidade para uma linha que já é Vivo.", "Solicitar abertura de incidente. Se o caso exigir migração, seguir com o pedido adequado, após validação da operação."], ["Cancelado", "Solicitação do cliente.", "Conforme o material, o cancelamento deve ocorrer até duas horas antes da portabilidade. Confirmar a janela com a operação."]];
function portabilityStatusHTML(){return `<section class="portability-reference"><h3>PORTABILIDADE BRAZ / VIVO · STATUS, CAUSAS E AÇÕES</h3><p class="hint">Referência do treinamento fornecido pela ITOP. Para Dry, confirme os códigos e procedimentos com a operação.</p><div class="portability-status-grid">${portabilityStatuses.map(([status,cause,action])=>`<article class="portability-status"><h4>${escapeHTML(status.toUpperCase())}</h4><p><b>CAUSA / SITUAÇÃO</b><br>${escapeHTML(cause)}</p><p class="status-action"><b>AÇÃO DO VENDEDOR</b><br>${escapeHTML(action)}</p></article>`).join('')}</div></section>`;}

let activeSupportTopic='internet',supportStatus='EM ATENDIMENTO';
