const supportProfiles={dry:{apn:'surf.br',user:'',pass:'',network:'',confirmed:false},braz:{apn:'',user:'',pass:'',network:'VIVO',confirmed:false}};
function currentSupportTopic(){return supportTopics.find(t=>t.id===activeSupportTopic);}
function currentSupportProfile(){return supportProfiles[$('supportOperation').value];}
function mountSupportBanner(){
 const context=$('supportOperation').closest('.support-context');
 const header=context.parentElement;
 const sidebar=$('supportSearch').closest('.support-sidebar');
 sidebar.parentElement.classList.add('support-layout-wide');
 const dialog=document.createElement('dialog');
 dialog.id='support-search-dialog';
 dialog.setAttribute('aria-labelledby','support-search-title');
 dialog.innerHTML='<div class="support-dialog-heading"><h2 id="support-search-title">Busca de Erros</h2><button type="button" aria-label="Fechar busca">Fechar</button></div>';
 dialog.append(...sidebar.children);
 sidebar.replaceWith(dialog);
 dialog.querySelector('button').onclick=()=>dialog.close();

 const banner=document.createElement('div');
 banner.className='support-banner';
 banner.innerHTML='<div class="support-banner-art" role="img" aria-label="Suporte a Telefonia Móvel · Problemas e Soluções"></div>';
 banner.append(context);
 const search=document.createElement('button');
 search.id='support-search-open';
 search.type='button';
 search.textContent='Busca de Erros';
 search.setAttribute('aria-haspopup','dialog');
 search.setAttribute('aria-controls',dialog.id);
 search.onclick=()=>{
  $('supportSearch').value='';
  renderSupportTopics();
  dialog.showModal();
  $('supportSearch').focus();
 };
 banner.append(search);
 header.replaceChildren(banner,$('supportLineChoices'));

 const style=document.createElement('style');
 style.textContent=`
 #movel .support-layout.support-layout-wide{display:block}
 #movel .support-banner{position:relative;container-type:inline-size}
 #movel .support-banner-art{aspect-ratio:2009/783;background:url(data:image/webp;base64,) center top/100% auto no-repeat}
 #movel .support-banner .support-context{position:absolute;inset:56% 1.55% auto 25.5%;display:grid;grid-template-columns:22.6fr 22.9fr 24.5fr 25.9fr;gap:1.1cqw;margin:0}
 #movel .support-banner .field{min-width:0;margin:0}
 #movel .support-banner .field>label{position:absolute;clip-path:inset(50%);width:1px;height:1px;overflow:hidden;white-space:nowrap}
 #movel .support-banner :is(input,select){box-sizing:border-box;width:100%;min-width:0;height:4.2cqw;min-height:0;margin:0;padding:0 .5cqw;border:2px solid #ff6700;border-radius:1cqw;background:#fff;color:#111;font-size:clamp(10px,1.45cqw,22px);text-align:center}
 #movel #support-search-open{position:absolute;inset:75% 1.5% 10% 25%;width:auto;margin:0;background:transparent!important;border:0!important;box-shadow:none!important;color:transparent!important;-webkit-text-fill-color:transparent!important;text-shadow:none!important}
 #movel #support-search-open:focus-visible{outline:3px solid #ff7900;outline-offset:2px}
 #movel #support-search-dialog{box-sizing:border-box;width:min(680px,94vw);max-height:85dvh;padding:20px;border:2px solid #d27a2f;border-radius:14px;background:#fff;color:#111;overflow:auto}
 #movel #support-search-dialog::backdrop{background:#0009}
 #movel .support-dialog-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}
 #movel .support-dialog-heading h2{margin:0}
 #movel #supportTopics{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,230px),1fr));gap:6px;margin-top:12px}
 #movel #supportTopics button{min-width:0;white-space:normal;text-align:left}
 @container (max-width:820px){
  #movel .support-banner-art{aspect-ratio:2009/245;border-radius:10px}
  #movel .support-banner .support-context{position:static;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:12px 0}
  #movel .support-banner .field>label{position:static;clip-path:none;width:auto;height:auto;overflow:visible;white-space:normal}
  #movel .support-banner :is(input,select){height:42px;padding:0 6px;border-radius:8px;font-size:14px}
  #movel #support-search-open{position:static;width:100%;min-height:40px!important;background:#525254!important;color:#fff!important;-webkit-text-fill-color:#fff!important}
 }
 `;
 document.head.append(style);
}

function initMobileSupport(){
 if(!$('supportNumber').value)$('supportNumber').value=$('telefone').value;
 $('supportLineChoices').replaceChildren();
 for(let i=0;i<5;i++){const number=$('mnumero'+i).value;if(!number)continue;const b=document.createElement('button');b.type='button';b.textContent='ATENDER MÓVEL '+(i+1)+' · '+number;b.addEventListener('click',()=>{$('supportNumber').value=number;});$('supportLineChoices').append(b);}
 renderSupportTopics();renderSupportGuide();
}
function renderSupportTopics(){const q=$('supportSearch').value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();$('supportTopics').innerHTML=supportTopics.filter(t=>(t.title+' '+t.id+(t.id==='portability'?' '+portabilityStatuses.flat().join(' '):'')).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q)).map(t=>`<button type="button" class="support-topic ${t.id===activeSupportTopic?'active':''}" data-topic="${t.id}">${escapeHTML(t.title)}</button>`).join('')||'<p class="hint">Nenhum assunto encontrado.</p>';}
function baseCustomerSupportSteps(){
 const id=activeSupportTopic,d=mobilePaths[$('supportDevice').value],p=currentSupportProfile(),dry=$('supportOperation').value==='dry',onIphone=$('supportDevice').value==='iphone';
 const test='Desligue o Wi-Fi, teste um site e nos informe se a internet voltou.';
 const common=['Abra '+d.data+' e selecione a linha ITOP para internet.','Ative os dados móveis.','Ative o modo avião por 15 segundos e desative.','Reinicie o aparelho.',test];
 if(id==='quota')return dry?['Abra o discador do celular.','Digite *225# e toque em Ligar usando a linha ITOP.','Aguarde a resposta e confira os dados disponíveis.','Se não aparecer resposta, informe o aviso recebido ao atendimento.']:['Abra o aplicativo Mensagens (SMS), não o WhatsApp.','Crie um SMS para 1058 com a palavra DADOS.','Envie usando a linha ITOP.','Aguarde a resposta e confira os dados disponíveis.'];
 if(id==='dual')return ['Confirme com o atendimento se a portabilidade já foi concluída. Antes disso, mantenha o chip antigo disponível.',...(onIphone?['Se usar eSIM, identifique a linha ITOP pelo número ou etiqueta; não apague o eSIM.']:['Após a conclusão confirmada, se possível, desligue o aparelho e coloque o chip físico ITOP no slot 1. O slot não define sozinho a linha padrão.']), 'Abra '+d.dual+'.','Defina a linha ITOP para dados móveis e chamadas. Escolha a linha ITOP para SMS no gerenciador ou no aplicativo Mensagens.','Se houver troca automática de dados entre chips, desative-a durante o teste.','Somente após a portabilidade concluída, desative temporariamente a linha antiga nas configurações para testar.',test,'Faça também uma ligação e um SMS de teste.'];
 if(id==='apn')return ['Antes de alterar, anote a configuração de APN atual.','Abra '+d.apn+'.',...(onIphone?['Se o menu não aparecer, pare e avise o atendimento.']:['Toque em Adicionar / + para criar o perfil. No campo Nome, use ITOP.']), 'No campo APN, digite exatamente: '+(p.apn||'[AGUARDANDO CONFIRMAÇÃO TÉCNICA]')+'.', 'Nome de usuário: '+(p.user||'deixe em branco conforme a configuração confirmada')+'.','Senha: '+(p.pass||'deixe em branco conforme a configuração confirmada')+'.','Mantenha os demais parâmetros como orientados pelo atendimento; não altere MCC/MNC por tentativa.',onIphone?'Volte à tela anterior para manter os ajustes.':'Toque em Salvar e selecione o perfil criado.',test];
 if(id==='manual')return ['Abra '+d.network+'.','Selecione a linha ITOP, se o aparelho perguntar.','Desative a seleção automática e aguarde a busca terminar.','Selecione somente a rede indicada pelo atendimento: '+(p.network||'[REDE A CONFIRMAR]')+'.','Aguarde o registro e teste uma ligação e a internet com o Wi-Fi desligado.','Se não conectar ou aparecer rede proibida, volte à seleção automática e informe o aviso ao atendimento.'];
 if(id==='automatic')return ['Abra '+d.network+'.','Selecione a linha ITOP, se necessário.','Ative Selecionar automaticamente / Automática.','Aguarde o sinal se registrar na rede.',test];
 if(id==='roaming')return ['Confirme com o atendimento se o roaming de dados é necessário e está autorizado para sua linha e local. No exterior, confirme antes as condições e possíveis cobranças.','Abra '+d.roam+'.','Com a confirmação do atendimento, ative o roaming somente para a linha ITOP.',test];
 if(id==='five')return ['Verifique com o atendimento se aparelho, linha e local têm suporte a 5G.','Abra '+d.five+'.','Se disponível, selecione '+(onIphone?'5G Automático':'5G/4G automático ou Preferir 5G')+'.','Se a opção não aparecer, informe o modelo do aparelho ao atendimento.','O modo automático pode usar 4G mesmo com 5G habilitado; teste a conexão e informe o local.'];
 if(id==='signal')return ['Abra '+d.base+' e confira se a linha ITOP está ativada.','Ative o modo avião por 15 segundos e depois desative.','Reinicie o aparelho.','Teste em outro local, de preferência em ambiente externo seguro.','Se continuar sem serviço, informe o aviso na tela e se o chip é reconhecido.'];
 if(id==='slow')return ['Desligue o Wi-Fi para testar a rede móvel.','Abra '+d.data+' e confira se a linha ITOP está selecionada.','Pause downloads e o compartilhamento de internet durante o teste.','Teste outro site ou aplicativo.','Compare em outro local e horário e informe os resultados ao atendimento.'];
 if(id==='calls')return ['Confira em '+d.dual+' se a linha ITOP está selecionada para ligações.','Faça uma ligação de teste e peça para alguém ligar para seu número.','Informe se a falha é para fazer, receber ou ambos e qual aviso aparece.','Verifique se o problema acontece com todos os números e se a internet móvel funciona.'];
 if(id==='sms')return ['Confirme que a linha ITOP está ativa e que o aplicativo Mensagens usa o chip correto.','Confira a pasta de spam e os números bloqueados.','Teste um SMS comum e informe se ele chega.','Se só o código de um aplicativo falhar, informe qual aplicativo e o horário. Não compartilhe seus códigos de confirmação.'];
 if(id==='activation')return ['Confirme com o atendimento que a ativação já foi concluída.','Abra '+d.base+' e confira se a linha ITOP está habilitada.',onIphone?'Se usar eSIM, não exclua o perfil; informe se ele aparece nos ajustes.':'Se for chip físico, desligue o aparelho antes de retirar e recolocar o chip.','Reinicie e informe se aparece Sem SIM, SIM inválido ou Sem serviço.'];
 if(id==='dry-port')return ['Confirme com nosso atendimento se a solicitação está liberada após a instalação e ativação da fibra.','Apresente comprovante de titularidade do número atual (conta ou tela do aplicativo da operadora).','Mantenha o número antigo ativo e disponível para receber o SMS de confirmação.','Após receber a mensagem legítima de confirmação, confira os dados e responda SIM.','Guarde o chip Dry e aguarde a conclusão informada pelo atendimento, normalmente em 3 a 5 dias úteis.','Não cancele a linha antiga antes da conclusão. Em caso de dúvida, ligue 10543.'];
 if(id==='dry-port-errors')return ['Informe ao atendimento o número com DDD e em qual etapa ocorreu o problema.','Se não recebeu o SMS, mantenha o chip antigo ativo e avise o atendimento; não repita pedidos por conta própria.','Caso seja solicitada nova comprovação, encaminhe-a apenas pelo canal oficial indicado.','Não cancele nem descarte os chips até o suporte confirmar a solução.'];
 if(id==='braz-port')return ['Confirme com nosso atendimento a liberação do pedido após a instalação e ativação da fibra.','Apresente comprovante da titularidade e do tipo de plano da sua operadora atual.','Se sua linha for Vivo, confirme com a Vivo se ela está em pré-pago antes de solicitar a migração.','Se sua linha for de outra operadora, mantenha o chip antigo ativo para receber o SMS de confirmação.','Quando chegar a solicitação legítima por SMS, confira os dados e responda SIM.','Aguarde o prazo informado pelo atendimento e não cancele sua linha antiga antes da conclusão.'];
 if(id==='portability')return ['Confirme com o atendimento o status da portabilidade.','Enquanto estiver pendente, mantenha o chip antigo disponível.','Após a conclusão confirmada, confira em '+d.dual+' a preferência da linha ITOP.','Teste chamadas de entrada, saída, SMS e internet.','Informe em qual chip o número recebe chamadas. Não exclua o eSIM nem solicite nova portabilidade por tentativa.'];
 if(id==='recharge')return ['Confira o número para o qual a recarga foi realizada.','Informe ao atendimento a data, o valor e o canal de pagamento.','Envie o comprovante somente pelo canal oficial de atendimento.','Aguarde a verificação antes de fazer outra recarga para tentar resolver.'];
 if(id==='pin')return ['Não tente códigos de PIN ou PUK por adivinhação.','Informe ao atendimento a mensagem exata que aparece na tela, sem informar senhas pessoais.','Aguarde a orientação do canal autorizado para recuperar o acesso ao chip.'];
 if(id==='coverage')return ['Informe endereço completo e CEP do local com falha.','Diga se o sinal falha dentro do imóvel, na rua ou nos dois ambientes.','Se for seguro, compare a conexão perto de uma janela e em ambiente externo.','Informe o horário e se aparece 4G, 5G, Sem serviço ou SOS.','Não suba em telhados nem acesse locais de risco para procurar sinal.'];
 return common;
}
function supportQuotaSteps(){return $('supportOperation').value==='dry'?[
 'Antes dos ajustes, abra o discador, digite *225# e toque em Ligar usando a linha ITOP para consultar o pacote de dados.',
 'Tire um print da resposta com o pacote de dados e envie ao atendimento ITOP para avaliação. Se a consulta não funcionar, envie um print do aviso apresentado.'
 ]:[
 'Antes dos ajustes, abra o aplicativo Mensagens (SMS), envie a palavra DADOS para 1058 usando a linha ITOP. Não é mensagem pelo WhatsApp.',
 'Tire um print da resposta com o pacote de dados e envie ao atendimento ITOP para avaliação. Se a consulta não funcionar, envie um print do aviso apresentado.'
 ];}
function supportWifiPath(){return {
 iphone:'Ajustes → Celular → linha ITOP → Ligações Wi-Fi → Ligações Wi-Fi Neste iPhone',
 samsung:'Configurações → Conexões → Chamadas Wi-Fi (ou Telefone → ⋮ → Configurações → Chamadas Wi-Fi)',
 motorola:'Configurar → Rede e internet → Chips → linha ITOP → Ligações Wi-Fi (ou Telefone → Configurações → Contas de chamada)',
 xiaomi:'Configurações → Cartões SIM e redes móveis / Redes móveis → linha ITOP → Fazer chamadas usando Wi-Fi'
 }[$('supportDevice').value];}
function supportEssentialSteps(){const d=mobilePaths[$('supportDevice').value];return [
 'Mantenha o roaming de dados ATIVADO na linha ITOP: '+d.roam+'. Esta orientação é para uso nacional; no exterior, confirme as condições com o atendimento antes de ativar.',
 'Mantenha as chamadas por Wi-Fi ATIVADAS, quando disponíveis: '+supportWifiPath()+'. Se a opção não aparecer ou não ativar, informe ao atendimento para verificar o suporte do aparelho e da linha.',
 'Para testar a internet móvel, desligue apenas a conexão Wi-Fi durante o teste e depois reconecte-a. Mantenha a opção Chamadas por Wi-Fi ativada; ela é diferente do botão Wi-Fi.'
 ];}
function customerSupportSteps(){
 const prerequisite=activeSupportTopic==='pin'?['Se o chip pedir PIN ou PUK, não tente códigos por adivinhação. Faça a consulta e os ajustes abaixo somente após a liberação pelo canal autorizado.']:[];
 return [...prerequisite,...supportQuotaSteps(),...supportEssentialSteps(),...(activeSupportTopic==='quota'?[]:baseCustomerSupportSteps())];
}
function supportEssentialChecklist(){return [
 'Cliente orientado a consultar o pacote de dados na linha correta',
 'Print da consulta recebido e avaliado (ou falha da consulta registrada)',
 'Roaming de dados ativo na linha ITOP, em uso nacional',
 'Chamadas por Wi-Fi ativas, ou ausência/incompatibilidade registrada'
 ];}
function supportEssentialBanner(){const command=$('supportOperation').value==='dry'?'LIGAR *225# NA LINHA ITOP':'SMS DADOS PARA 1058 NA LINHA ITOP';return `<div class="support-essential"><span class="eyebrow">PRIMEIRO PASSO EM TODO ATENDIMENTO</span><strong>${command}</strong><p>Peça o print da resposta e avalie o pacote antes dos ajustes. Se não for possível consultar por falta de sinal ou bloqueio, registre o erro e prossiga com o diagnóstico.</p><div class="support-essential-tags"><span>ROAMING DE DADOS: ATIVO</span><span>VOZ POR WI-FI: ATIVA, QUANDO DISPONÍVEL</span></div><p class="hint">Uso nacional. Não confundir ativação de chamadas por Wi-Fi com manter o Wi-Fi conectado durante o teste dos dados móveis.</p></div>`;}
function supportBlocked(){const p=currentSupportProfile();if(activeSupportTopic==='apn'&&(!p.confirmed||!p.apn.trim()))return 'Confirme os parâmetros de APN desta linha antes de copiar ou enviar a configuração.';if(activeSupportTopic==='manual'&&(!p.confirmed||!p.network.trim()))return 'Confirme a rede autorizada para esta linha antes de copiar ou enviar a busca manual.';return '';}
function supportCustomerText(){const d=mobilePaths[$('supportDevice').value];return '*ITOP · '+currentSupportTopic().title+'*\nAparelho: '+d.name+'\n\n'+customerSupportSteps().map((s,i)=>(i+1)+'. '+s).join('\n\n')+'\n\nOs nomes dos menus podem variar por modelo e versão. Se a opção não aparecer, avise o atendimento ITOP antes de alterar outra configuração.';}
function renderSupportGuide(){
 const t=currentSupportTopic(),p=currentSupportProfile(),checks=[...supportEssentialChecklist(),...t.checks];const list=items=>'<ul>'+items.map(s=>'<li>'+escapeHTML(s)+'</li>').join('')+'</ul>';
 let profile='';
 if(['apn','manual'].includes(t.id))profile=`<div class="support-profile"><h3>PARÂMETROS DESTA LINHA · USO DO VENDEDOR</h3><p class="hint">${$('supportOperation').value==='dry'?'APN surf.br consta no guia oficial Dry. Confirme os demais campos e a rede permitida para a linha ITOP.':'APN Braz pendente de ficha técnica oficial. Preencha somente após confirmação do parceiro; não presuma a APN da Vivo.'}</p><div class="grid">${t.id==='apn'?`<div class="field"><label>APN exata</label><input id="supportAPN" data-exact value="${escapeHTML(p.apn)}" placeholder="CONFIRMAR COM A OPERAÇÃO"></div><div class="field"><label>Usuário · em branco se confirmado</label><input id="supportAPNUser" data-exact value="${escapeHTML(p.user)}"></div><div class="field"><label>Senha APN · em branco se confirmado</label><input id="supportAPNPass" data-exact value="${escapeHTML(p.pass)}" autocomplete="off"></div>`:`<div class="field"><label>Rede autorizada · nome exibido na busca</label><input id="supportNetwork" value="${escapeHTML(p.network)}" placeholder="REDE CONFIRMADA PARA A LINHA"></div>`}</div><label class="support-check support-select-network"><input type="checkbox" id="supportConfirmed" ${p.confirmed?'checked':''}>Conferi os parâmetros com a operação para esta linha.</label></div>`;
 const coverage=t.id==='coverage'||t.id==='signal'?`<div class="support-map-links"><a href="https://www.tim.com.br/para-voce/cobertura-e-roaming/mapa-de-cobertura" target="_blank" rel="noopener">Dry - cobertura</a><a class="support-map-braz" href="https://vivo.com.br/para-voce/por-que-vivo/qualidade/cobertura" target="_blank" rel="noopener">Braz Cobertura</a><a href="https://www.brazmovel.com.br/" target="_blank" rel="noopener">BRAZ · SITE OFICIAL</a><a href="https://sistemas.anatel.gov.br/se/public/cmap.php" target="_blank" rel="noopener">ANATEL · REFERÊNCIA DE SINAL</a></div><p class="hint">Braz: consulte a cobertura da rede Vivo por endereço e tecnologia. Confirme com o parceiro a disponibilidade para a linha; o mapa não garante sinal dentro de cada imóvel.</p>`:'';
 $('supportGuide').innerHTML=`<div class="support-guide-head"><div><span class="eyebrow">ROTEIRO DE ATENDIMENTO</span><h2>${escapeHTML(t.title)}</h2></div><span class="section-tag">${mobilePaths[$('supportDevice').value].name.toUpperCase()}</span></div>${supportEssentialBanner()}<div class="support-checklist support-baseline-checks">${supportEssentialChecklist().map((c,i)=>`<label class="support-check"><input class="support-check-done" type="checkbox" data-index="${i}" ${(supportChecks[supportContextKey()]||[]).includes(i)?'checked':''}>${escapeHTML(c)}</label>`).join('')}</div><div class="support-internal"><h3>1 · O QUE PERGUNTAR</h3>${list(t.ask)}</div><div class="support-internal"><h3>2 · O QUE CONFERIR INTERNAMENTE</h3>${list(t.system)}</div>${coverage}${profile}${t.id==='portability'?portabilityStatusHTML():''}<h3>3 · TESTES E CONFERÊNCIAS REALIZADOS</h3><div class="support-checklist">${t.checks.map((c,i)=>`<label class="support-check"><input class="support-check-done" type="checkbox" data-index="${i+4}" ${(supportChecks[supportContextKey()]||[]).includes(i+4)?'checked':''}>${escapeHTML(c)}</label>`).join('')}</div><div class="support-escalation"><b>QUANDO ENCAMINHAR</b><br>${escapeHTML(t.escalate)}</div><p class="hint">As instruções para o aparelho estão abaixo, no texto que pode ser enviado ao cliente.</p>`;
 updateSupportMessage();
}
function updateSupportMessage(){const blocked=supportBlocked();$('supportMessage').textContent=supportCustomerText();$('supportCopy').disabled=!!blocked;$('supportWhatsApp').disabled=!!blocked;$('supportSendStatus').textContent=blocked;}
function supportSummary(){const t=currentSupportTopic();const done=[...document.querySelectorAll('.support-check-done:checked')].map(e=>[...supportEssentialChecklist(),...t.checks][Number(e.dataset.index)]);return ['ATENDIMENTO MÓVEL ITOP · RESUMO INTERNO','CLIENTE: '+($('nome').value||'NÃO INFORMADO'),'LINHA: '+($('supportNumber').value||'NÃO INFORMADA'),'OPERAÇÃO: '+($('supportOperation').value==='dry'?'DRY CONECTA':'BRAZ MÓVEL'),'APARELHO: '+mobilePaths[$('supportDevice').value].name+' · '+($('supportModel').value||'MODELO NÃO INFORMADO'),'ASSUNTO: '+t.title,'LOCAL: '+($('supportPlace').value||'NÃO INFORMADO'),'INÍCIO / HORÁRIO: '+($('supportSince').value||'NÃO INFORMADO'),'ERRO: '+($('supportError').value||'NÃO INFORMADO'),'CONFERÊNCIAS REALIZADAS: '+(done.join('; ')||'NENHUMA MARCADA'),'OBSERVAÇÕES: '+($('supportNotes').value||'NÃO INFORMADAS'),'STATUS: '+supportStatus,'DATA: '+new Date().toLocaleString('pt-BR')].join('\n');}
async function copySupportText(text){try{if(!navigator.clipboard?.writeText)throw Error('clipboard');await navigator.clipboard.writeText(text);return true;}catch{const e=document.createElement('textarea');e.value=text;e.style.position='fixed';e.style.left='-9999px';document.body.append(e);e.select();let ok=false;try{ok=document.execCommand('copy');}catch{}e.remove();return ok;}}
async function copyCustomerSupport(){if(supportBlocked())return;const ok=await copySupportText(supportCustomerText());$('supportSendStatus').textContent=ok?'Instruções copiadas. Cole na conversa já aberta do cliente.':'Não foi possível copiar automaticamente. Selecione o texto acima e copie manualmente.';}
function sendCustomerSupport(){if(supportBlocked())return;const raw=$('supportNumber').value.replace(/\D/g,'');if(raw.length!==11){$('supportSendStatus').textContent='Informe o WhatsApp do cliente com DDD e 11 dígitos.';return;}const msg=encodeURIComponent(supportCustomerText()),mobile=/Android|iPhone|iPad|iPod/i.test(navigator.userAgent);window.open((mobile?'https://wa.me/55'+raw+'?text=':'https://web.whatsapp.com/send?phone=55'+raw+'&text=')+msg,'ITOP_SUPORTE_WHATSAPP');$('supportSendStatus').textContent='Mensagem preparada para você revisar e enviar. Para usar uma conversa já aberta sem carregar outra aba, prefira Copiar instruções.';}
$('supportTopics').addEventListener('click',e=>{const b=e.target.closest('[data-topic]');if(!b)return;activeSupportTopic=b.dataset.topic;const operation=currentSupportTopic().operation;if(operation&&operation!==$('supportOperation').value){$('supportOperation').value=operation;currentSupportProfile().confirmed=false;}$('support-search-dialog').close();supportStatus='EM ATENDIMENTO';$('supportOutcome').textContent=supportStatus;renderSupportTopics();renderSupportGuide();$('supportReport').hidden=true;});
$('supportSearch').addEventListener('input',renderSupportTopics);
$('supportOperation').addEventListener('change',()=>{const operation=currentSupportTopic().operation;if(operation&&operation!==$('supportOperation').value)activeSupportTopic='internet';currentSupportProfile().confirmed=false;renderSupportTopics();renderSupportGuide();});$('supportDevice').addEventListener('change',()=>{currentSupportProfile().confirmed=false;renderSupportGuide();});
$('movel').addEventListener('input',e=>{const el=e.target;if(el.id==='supportNumber')el.value=el.value.replace(/\D/g,'').slice(0,11);else if(el.matches('input:not([data-exact]):not([type=checkbox]),textarea')&&el.id!=='supportSearch')el.value=el.value.toLocaleUpperCase('pt-BR');const keys={supportAPN:'apn',supportAPNUser:'user',supportAPNPass:'pass',supportNetwork:'network'};if(keys[el.id]){const p=currentSupportProfile();p[keys[el.id]]=el.value;p.confirmed=false;if($('supportConfirmed'))$('supportConfirmed').checked=false;updateSupportMessage();}});
$('movel').addEventListener('change',e=>{if(e.target.matches('.support-check-done'))supportChecks[supportContextKey()]=[...document.querySelectorAll('.support-check-done:checked')].map(e=>Number(e.dataset.index));if(e.target.id==='supportConfirmed'){currentSupportProfile().confirmed=e.target.checked;updateSupportMessage();}});
$('supportCopy').addEventListener('click',copyCustomerSupport);$('supportWhatsApp').addEventListener('click',sendCustomerSupport);
$('supportResolved').addEventListener('click',()=>{supportStatus='RESOLVIDO';$('supportOutcome').textContent=supportStatus;$('supportReport').hidden=false;$('supportReport').textContent=supportSummary();});
$('supportEscalate').addEventListener('click',()=>{supportStatus='ENCAMINHAR AO SUPORTE';$('supportOutcome').textContent=supportStatus;$('supportReport').hidden=false;$('supportReport').textContent=supportSummary();});
$('supportCopyReport').addEventListener('click',async()=>{$('supportReport').hidden=false;$('supportReport').textContent=supportSummary();const ok=await copySupportText(supportSummary());$('supportSendStatus').textContent=ok?'Resumo interno copiado. Registre no canal autorizado de suporte.':'Selecione e copie manualmente o resumo interno abaixo.';});
function resetMobileSupport(){for(const k of Object.keys(supportChecks))delete supportChecks[k];supportProfiles.dry={apn:'surf.br',user:'',pass:'',network:'',confirmed:false};supportProfiles.braz={apn:'',user:'',pass:'',network:'VIVO',confirmed:false};activeSupportTopic='internet';supportStatus='EM ATENDIMENTO';$('supportOutcome').textContent=supportStatus;$('supportReport').hidden=true;$('supportReport').textContent='';initMobileSupport();}
mountSupportBanner();
